wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

const MAX_QUESTION_CHARS: usize = 512;
const NO_KNOWLEDGE: &str = "No relevant knowledge-base entries were found for this question.";

struct Node;

/// Truncate to at most `max` Unicode scalar values (Python `len` semantics),
/// always on a char boundary.
fn bound_chars(s: String, max: usize) -> String {
    match s.char_indices().nth(max) {
        Some((idx, _)) => s[..idx].to_string(),
        None => s,
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;

        // `requires` already bounds the question; re-bounding is a no-op on valid
        // input and guarantees the `ensures len(question) <= 512` regardless.
        let question = bound_chars(q.question, MAX_QUESTION_CHARS);

        // Read-only lookup against the knowledge base: the only capability held.
        let mut knowledge: Vec<String> = kb_read::lookup(&question)
            .into_iter()
            .filter(|entry| !entry.trim().is_empty())
            .collect();

        // `ensures present(knowledge)`: never emit an empty knowledge list.
        if knowledge.is_empty() {
            knowledge.push(NO_KNOWLEDGE.to_string());
        }

        ConversationContext {
            intent: q.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

